-- Tennessee had two stops, both Halloween attractions.
--
-- Three proximity flags kept: Oak Ridge's Manhattan Project sites sit forty
-- metres apart because that is how the reservation was laid out, and Memphis
-- puts the Blues Hall of Fame across the street from the National Civil
-- Rights Museum.
--
-- Tennessee, Alabama and Mississippi are Central time; so are Illinois,
-- Wisconsin and Louisiana. No county exceptions in any of the six.
--
-- 150 stops.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Synchronous Fireflies of the Great Smoky Mountains', 'synchronous-fireflies-of-the-great-smoky-mountains', 'roadside-oddities', 35.6552, -83.5817, 'Elkmont', 'TN', 'Each late spring, Photinus carolinus fireflies in the Elkmont area flash in coordinated waves, creating one of the Smokies'' strangest natural spectacles. The National Park Service controls peak-event access through a lottery and timed-entry system, so this is a seasonal, permit-dependent stop rather than a casual nighttime pull-off.', 'limited', 'https://www.nps.gov/grsm/learn/nature/fireflies.htm', null, 'America/Chicago', now()),
  ('The Lost Sea', 'the-lost-sea', 'roadside-oddities', 35.53493, -84.43198, 'Sweetwater', 'TN', 'Craighead Caverns contains a vast underground lake explored by guided boat tour. The commercial cave mixes unusual geology, Civil War-era history and an enormous subterranean body of water, making it one of Tennessee''s strongest true roadside-underground attractions.', 'limited', 'https://thelostsea.com/', null, 'America/Chicago', now()),
  ('Forbidden Caverns', 'forbidden-caverns', 'roadside-oddities', 35.9042, -83.34685, 'Sevierville', 'TN', 'Guided tours descend through a large cave system once associated with Eastern Woodland peoples and later moonshiners. Illuminated formations, underground streams and the cavern''s regional history give it a much stranger character than a typical scenic stop.', 'limited', 'https://www.forbiddencavern.com/', null, 'America/Chicago', now()),
  ('The Evil Dead Cabin Site', 'the-evil-dead-cabin-site', 'weird-history', 36.22263, -83.37659, 'Morristown', 'TN', 'The remote property associated with the cabin used in Sam Raimi''s original The Evil Dead has become a cult-horror pilgrimage point. The cabin itself is gone and the land is private; OddWay visitors should never enter the property or attempt to hunt for remnants beyond lawful public access.', 'private', 'https://www.atlasobscura.com/places/the-evil-dead-cabin-morristown-tennessee', null, 'America/Chicago', now()),
  ('Ruby Falls', 'ruby-falls', 'roadside-oddities', 35.0191, -85.3394, 'Chattanooga', 'TN', 'An elevator and guided cave route lead deep inside Lookout Mountain to a tall underground waterfall discovered during twentieth-century cave exploration. The combination of subterranean passages, unusual geology and the hidden waterfall makes Ruby Falls a classic Tennessee oddity.', 'limited', 'https://www.rubyfalls.com/', null, 'America/Chicago', now()),
  ('Raccoon Mountain Caverns', 'raccoon-mountain-caverns', 'roadside-oddities', 35.02122, -85.40793, 'Chattanooga', 'TN', 'Raccoon Mountain contains miles of mapped cave passage beneath the campground, with standard walking tours and more demanding wild-cave trips offered under controlled conditions. Its extensive network makes it a practical, legal alternative to unsafe abandoned-cave exploration.', 'limited', 'https://www.raccoonmountain.com/', null, 'America/Chicago', now()),
  ('Manhattan Project National Historical Park — Oak Ridge', 'manhattan-project-national-historical-park-oak-ridge', 'weird-history', 36.02319, -84.27205, 'Oak Ridge', 'TN', 'Oak Ridge was created in secrecy during World War II as a major Manhattan Project site. The National Park Service interprets the city, its wartime role and surviving facilities; some associated federal sites require scheduled tours or remain restricted, so visitors should use official visitor points only.', 'limited', 'https://www.nps.gov/mapr/planyourvisit/oakridge-tn.htm', null, 'America/Chicago', now()),
  ('Tuckaleechee Caverns', 'tuckaleechee-caverns', 'roadside-oddities', 35.65806, -83.77419, 'Townsend', 'TN', 'These privately operated caverns take visitors beneath the Smokies through large rooms, unusual formations and an underground waterfall. The cave has been a long-running Tennessee roadside attraction and remains accessible only through posted tour operations.', 'limited', 'https://tuckaleecheecaverns.com/', null, 'America/Chicago', now()),
  ('Elkmont Historic District', 'elkmont-historic-district', 'weird-history', 35.65429, -83.58057, 'Elkmont', 'TN', 'Elkmont grew from a logging settlement into a resort community before much of it was absorbed into Great Smoky Mountains National Park. Preserved cabins, restored structures and traces of vanished buildings create a rare legal-to-explore ghost-of-a-resort landscape.', 'open', 'https://www.nps.gov/grsm/learn/historyculture/elkmont-historic-district.htm', null, 'America/Chicago', now()),
  ('Lookout Mountain Incline Railway', 'lookout-mountain-incline-railway', 'roadside-oddities', 35.00778, -85.33556, 'Chattanooga', 'TN', 'This historic funicular climbs Lookout Mountain on a grade that becomes dramatically steep near the summit. The unusual rail engineering and nearly vertical-looking ride make the Incline itself the attraction rather than simply transportation to a viewpoint.', 'limited', 'https://ridetheincline.com/', null, 'America/Chicago', now()),
  ('Titanic Museum Attraction', 'titanic-museum-attraction', 'roadside-oddities', 35.82055, -83.57894, 'Pigeon Forge', 'TN', 'A large ship-shaped museum rises beside the Pigeon Forge strip, recreating portions of RMS Titanic and displaying artifacts connected with the disaster. Its deliberately theatrical half-scale exterior makes it one of the state''s most visually unmistakable roadside museums.', 'limited', 'https://titanicattraction.com/pigeon-forge', null, 'America/Chicago', now()),
  ('Andrew Johnson Tailor Shop and National Historic Site', 'andrew-johnson-tailor-shop-and-national-historic-site', 'roadside-oddities', 36.16267, -82.82942, 'Greeneville', 'TN', 'The preserved tailor shop where Andrew Johnson worked before entering politics sits within his National Historic Site. The tiny trade shop offers an unusually intimate physical link to a president whose later impeachment and Reconstruction politics remain deeply contested parts of U.S. history.', 'open', 'https://www.nps.gov/anjo/index.htm', null, 'America/Chicago', now()),
  ('Fall Creek Falls State Park', 'fall-creek-falls-state-park', 'roadside-oddities', 35.65646, -85.35004, 'Spencer', 'TN', 'Deep gorges, caves, rock shelters and one of the tallest waterfalls in the eastern United States make this plateau landscape feel more geologically extreme than a standard state park. Stay on designated overlooks and trails around cliffs and sinkhole terrain.', 'open', 'https://tnstateparks.com/parks/fall-creek-falls', null, 'America/Chicago', now()),
  ('Historic Rugby', 'historic-rugby', 'weird-history', 36.36108, -84.70242, 'Rugby', 'TN', 'English author Thomas Hughes founded Rugby in 1880 as a utopian colony for younger sons of British families. Surviving Victorian buildings, a historic library, cemetery and preserved streets make the village a remarkably intact remnant of an ambitious social experiment.', 'limited', 'https://historicrugby.org/', null, 'America/Chicago', now()),
  ('Spaceship House', 'spaceship-house', 'roadside-oddities', 35.1063, -85.34841, 'Signal Mountain', 'TN', 'This saucer-shaped Futuro-style house looks like a landed spacecraft above the Tennessee River. It is a private residence rather than a public attraction, so travelers should view it only from lawful public areas and avoid disturbing occupants.', 'private', 'https://www.atlasobscura.com/places/spaceship-house', null, 'America/Chicago', now()),
  ('Salt & Pepper Shaker Museum', 'salt-pepper-shaker-museum', 'museums', 35.71623, -83.50247, 'Gatlinburg', 'TN', 'Tens of thousands of salt and pepper shakers fill this small museum, arranged by subject, era and design. The obsessive scale of the collection turns an ordinary tabletop object into one of Gatlinburg''s most genuinely eccentric museums.', 'open', 'https://thesaltandpeppershakermuseum.com/', null, 'America/Chicago', now()),
  ('Nickajack Cave Wildlife Refuge', 'nickajack-cave-wildlife-refuge', 'roadside-oddities', 34.99251, -85.61282, 'South Pittsburg', 'TN', 'Nickajack Cave was partly flooded by reservoir construction and now shelters major bat colonies. Visitors can observe the cave area from approved water or shoreline locations, especially during seasonal bat emergence; entering the cave or disturbing wildlife is not appropriate.', 'limited', 'https://www.tn.gov/twra/wildlife-management-areas/cumberland-plateau-r3/nickajack-cave-wma.html', null, 'America/Chicago', now()),
  ('Brushy Mountain State Penitentiary', 'brushy-mountain-state-penitentiary', 'weird-history', 36.10452, -84.44865, 'Petros', 'TN', 'The former maximum-security prison operated for more than a century and now offers authorized history tours, museum exhibits and selected paranormal programs. Cell blocks, yards and prison infrastructure are preserved, providing legal access to a place that would otherwise be strictly off limits.', 'limited', 'https://tourbrushy.com/', null, 'America/Chicago', now()),
  ('Chattanooga Choo Choo', 'chattanooga-choo-choo', 'weird-history', 35.03724, -85.30697, 'Chattanooga', 'TN', 'The former Terminal Station was transformed into a hotel-and-entertainment complex while retaining historic railcars and railroad architecture. Its name and identity were cemented by the famous big-band song, turning an old station into an unusually literal piece of pop-culture geography.', 'open', 'https://www.choochoo.com/', null, 'America/Chicago', now()),
  ('Backyard Terrors Dinosaur Park', 'backyard-terrors-dinosaur-park', 'roadside-oddities', 36.43913, -82.23112, 'Bluff City', 'TN', 'A backyard in northeast Tennessee evolved into a homemade dinosaur park filled with large creature sculptures and prehistoric scenes. The hand-built quality makes it feel closer to outsider art than a polished theme park; check current visitor hours before making the detour.', 'limited', 'https://www.atlasobscura.com/places/backyard-terrors-dinosaur-park', null, 'America/Chicago', now()),
  ('Fortress of Faith — Greenback Castle', 'fortress-of-faith-greenback-castle', 'roadside-oddities', 35.66119, -84.17214, 'Greenback', 'TN', 'Floyd Banks spent decades constructing towers, walls, tunnels and religiously themed concrete forms by hand, creating a sprawling castle-like environment on private property. Access depends on the owner''s current rules; visitors should never assume unrestricted entry.', 'limited', 'https://spacesarchives.org/explore/search-the-online-collection/floyd-banks-fortress-of-faith/', null, 'America/Chicago', now()),
  ('Sunsphere', 'sunsphere', 'roadside-oddities', 35.9617, -83.9232, 'Knoxville', 'TN', 'The gold-glass sphere built for the 1982 World''s Fair still rises above downtown Knoxville like a retro-futurist relic. Its observation level and surviving fairground context make it one of Tennessee''s most recognizable pieces of abandoned-future architecture.', 'limited', 'https://www.worldsfairpark.org/sunsphere', null, 'America/Chicago', now()),
  ('Foothills Parkway — The Missing Link', 'foothills-parkway-the-missing-link', 'weird-history', 35.68944, -83.8875, 'Townsend', 'TN', 'A long-unfinished section of the Foothills Parkway became known as the Missing Link because rugged terrain and engineering challenges delayed completion for decades. The finished roadway now lets travelers drive through a piece of National Park Service infrastructure history.', 'open', 'https://www.nps.gov/grsm/planyourvisit/foothillsparkway.htm', null, 'America/Chicago', now()),
  ('Abrams Creek Underwater Bridge', 'abrams-creek-underwater-bridge', 'weird-history', 35.55542, -83.99885, 'Tallassee', 'TN', 'A former road crossing near Abrams Creek was submerged by the creation of Chilhowee Lake, leaving bridge remains beneath the water. Conditions and visibility vary, and this should be treated as an observation/history stop rather than an invitation to enter the water or climb submerged structures.', 'limited', 'https://www.atlasobscura.com/places/abrams-creek-underwater-bridge', null, 'America/Chicago', now()),
  ('Walnut Street Bridge', 'walnut-street-bridge', 'weird-history', 35.0583, -85.3073, 'Chattanooga', 'TN', 'This long nineteenth-century truss bridge survived demolition and was converted into a pedestrian crossing over the Tennessee River. Its huge steel framework and adaptive reuse make it a walkable remnant of Chattanooga''s industrial-era transportation system.', 'open', 'https://www.atlasobscura.com/places/walnut-street-bridge', null, 'America/Chicago', now()),
  ('North Shore Dance Paving Stones', 'north-shore-dance-paving-stones', 'roadside-oddities', 35.06233, -85.30624, 'Chattanooga', 'TN', 'Embedded paving stones on Chattanooga''s North Shore diagram dance steps for pedestrians to follow. The installation turns an ordinary walkway into an interactive public-art lesson that many visitors cross without realizing what the markings mean.', 'open', 'https://www.atlasobscura.com/places/north-shore-dance-paving-stones', null, 'America/Chicago', now()),
  ('Millennium Manor', 'millennium-manor', 'roadside-oddities', 35.78, -83.965, 'Alcoa', 'TN', 'Built largely from stone in the 1930s, Millennium Manor was intended by its creators to survive catastrophic events and even the biblical apocalypse. It remains private property, making the strange survivalist house an exterior-only roadside curiosity unless the owner explicitly offers access.', 'private', 'https://www.atlasobscura.com/places/millennium-manor', null, 'America/Chicago', now()),
  ('Smoky Mountain Knife Works', 'smoky-mountain-knife-works', 'roadside-oddities', 35.93447, -83.58428, 'Sevierville', 'TN', 'This enormous knife store mixes retail with museum-like displays of blades, militaria, fossils, taxidermy and other curiosities. Its scale and eclectic interior make it function as a roadside cabinet of curiosities even for travelers not shopping for knives.', 'open', 'https://www.smkw.com/', null, 'America/Chicago', now()),
  ('Clinton 12 Statue and Green McAdoo Cultural Center', 'clinton-12-statue-and-green-mcadoo-cultural-center', 'weird-history', 36.10233, -84.1399, 'Clinton', 'TN', 'The site interprets the twelve Black students who integrated Clinton High School in 1956 after a federal court order. Outdoor figures and museum exhibits make the confrontation over school desegregation concrete without reducing it to a generic historical marker.', 'open', 'https://greenmcadoo.org/', null, 'America/Chicago', now()),
  ('Branner Cemetery Field Stones', 'branner-cemetery-field-stones', 'weird-history', 36.13081, -83.48377, 'Jefferson City', 'TN', 'Rows of rough fieldstones mark burials whose identities have largely been lost, creating a stark contrast with conventional carved headstones. The cemetery should be visited respectfully during lawful access hours and without moving or touching markers.', 'limited', 'https://www.atlasobscura.com/places/branner-cemetery-field-stones', null, 'America/Chicago', now()),
  ('Mountain Dew Headstone', 'mountain-dew-headstone', 'weird-history', 36.31472, -82.35667, 'Johnson City', 'TN', 'A cemetery marker celebrates the soft drink Mountain Dew with branding tied to the beverage''s East Tennessee origins. It is a compact piece of commercial folklore hidden among ordinary graves; visit respectfully and only during cemetery access.', 'limited', 'https://www.atlasobscura.com/places/mountain-dew-headstone', null, 'America/Chicago', now()),
  ('Prophet of Oak Ridge Grave', 'prophet-of-oak-ridge-grave', 'weird-history', 36.01241, -84.23387, 'Oak Ridge', 'TN', 'The grave of John Hendrix recalls a local figure whose pre-Manhattan Project visions were later interpreted as eerily anticipating the sudden wartime transformation of the area. The story sits at the intersection of prophecy folklore and Oak Ridge''s extraordinary twentieth-century history.', 'limited', 'https://www.atlasobscura.com/places/prophet-of-oak-ridge-grave', null, 'America/Chicago', now()),
  ('Knoxville Weather Kiosk', 'knoxville-weather-kiosk', 'roadside-oddities', 35.96398, -83.91865, 'Knoxville', 'TN', 'A vintage downtown weather kiosk preserves an era when public instruments displayed temperature and atmospheric information on the street. It is an easy-to-miss piece of civic technology surrounded by modern Knoxville.', 'open', 'https://www.atlasobscura.com/places/knoxville-weather-kiosk', null, 'America/Chicago', now()),
  ('World''s Largest Rubik''s Cube', 'worlds-largest-rubiks-cube', 'roadside-oddities', 35.96119, -83.9225, 'Knoxville', 'TN', 'A giant motorized Rubik''s Cube created for the 1982 World''s Fair survives in Knoxville as a piece of oversized puzzle history. Its continued presence gives the former fairgrounds another distinctly retro-futurist artifact.', 'open', 'https://www.atlasobscura.com/places/rubiks-cube', null, 'America/Chicago', now()),
  ('Sultana Disaster Memorial', 'sultana-disaster-memorial', 'weird-history', 35.90902, -83.93642, 'Knoxville', 'TN', 'A memorial in Mount Olive Cemetery honors East Tennessee soldiers lost in the 1865 explosion and sinking of the steamboat Sultana, one of the deadliest maritime disasters in U.S. history. Visit as a cemetery memorial rather than a novelty stop.', 'limited', 'https://www.knoxhistoryproject.org/sultana/', null, 'America/Chicago', now()),
  ('Old Gray Cemetery', 'old-gray-cemetery', 'weird-history', 35.97423, -83.92587, 'Knoxville', 'TN', 'Established in the nineteenth century, Old Gray is filled with elaborate monuments, Victorian funerary art and the graves of prominent East Tennesseans. Its sculpture and symbolism make it an outdoor museum of death customs, but normal cemetery etiquette applies.', 'limited', 'https://www.oldgraycemetery.org/', null, 'America/Chicago', now()),
  ('Headless General John Sevier Statue', 'headless-general-john-sevier-statue', 'roadside-oddities', 35.96378, -83.91829, 'Knoxville', 'TN', 'A statue of Tennessee''s first governor acquired a strange visual reputation because its composition and viewing angle can make the figure appear headless from certain positions. The effect turns an otherwise formal civic monument into a small downtown visual oddity.', 'open', 'https://www.atlasobscura.com/places/gen-john-sevier-statue', null, 'America/Chicago', now()),
  ('Mayna Treanor Avent Studio', 'mayna-treanor-avent-studio', 'roadside-oddities', 35.63795, -83.58599, 'Gatlinburg', 'TN', 'Artist Mayna Treanor Avent used a small Appalachian cabin as a studio, preserving a rare combination of vernacular mountain architecture and early Smokies art history. Reaching the site requires trail access and conditions can vary.', 'limited', 'https://www.atlasobscura.com/places/mayna-treanor-avent-studio', null, 'America/Chicago', now()),
  ('Ciderville Music Store', 'ciderville-music-store', 'roadside-oddities', 36.02867, -84.09225, 'Powell', 'TN', 'This old-school music store became known for bluegrass, country instruments and an atmosphere that feels more like a regional music clubhouse than conventional retail. Hours can be irregular, so travelers should check ahead before making it a dedicated detour.', 'limited', 'https://www.atlasobscura.com/places/ciderville-music-store', null, 'America/Chicago', now()),
  ('Dolly Parton Statue', 'dolly-parton-statue', 'weird-history', 35.86772, -83.56604, 'Sevierville', 'TN', 'A bronze Dolly Parton sits with a guitar outside the Sevier County Courthouse in her hometown. The unusually approachable monument has become a pilgrimage point connecting one of Tennessee''s most famous performers directly to the place where her story began.', 'open', 'https://www.atlasobscura.com/places/dolly-parton-statue', null, 'America/Chicago', now()),
  ('Lodge Museum of Cast Iron', 'lodge-museum-of-cast-iron', 'museums', 35.01101, -85.70276, 'South Pittsburg', 'TN', 'Lodge''s museum explains cast-iron manufacturing and cookware history while displaying an enormous skillet billed as the world''s largest. The mix of industrial history and intentionally oversized cookware makes this an especially strong OddWay museum stop.', 'open', 'https://www.lodgecastiron.com/pages/museum', null, 'America/Chicago', now()),
  ('Bush''s Beans Visitor Center', 'bushs-beans-visitor-center', 'roadside-oddities', 35.92979, -83.33934, 'Chestnut Hill', 'TN', 'The Bush''s visitor center turns baked-bean history into a museum experience with company artifacts, interactive displays and unapologetically bean-themed photo opportunities. It is an unusually elaborate monument to a grocery-shelf product born in East Tennessee.', 'open', 'https://bushbeans.com/en_US/about-us/visitor-center', null, 'America/Chicago', now()),
  ('Sequoyah Birthplace Museum', 'sequoyah-birthplace-museum', 'weird-history', 35.5068, -84.19487, 'Vonore', 'TN', 'This museum interprets Sequoyah, creator of the Cherokee syllabary, near his traditional birthplace in the Tennessee Valley. Exhibits place the writing system within Cherokee history and survival rather than treating Sequoyah as a roadside curiosity.', 'open', 'https://sequoyahmuseum.org/', null, 'America/Chicago', now()),
  ('Ducktown Basin Museum and Burra Burra Mine', 'ducktown-basin-museum-and-burra-burra-mine', 'weird-history', 35.0276, -84.3872, 'Ducktown', 'TN', 'The museum occupies the former headquarters of a copper-mining operation in a landscape once heavily damaged by smelting and deforestation. Mining artifacts, the Burra Burra Mine site and the basin''s environmental recovery make this a stark industrial-history stop.', 'limited', 'https://ducktownbasinmuseum.com/', null, 'America/Chicago', now()),
  ('Rhea County Courthouse — Scopes Trial Museum', 'rhea-county-courthouse-scopes-trial-museum', 'weird-history', 35.495, -85.01306, 'Dayton', 'TN', 'The 1925 Scopes ''Monkey Trial'' over teaching evolution unfolded inside this courthouse. A museum and preserved courtroom connect visitors to one of America''s most famous clashes over science, religion, education and law.', 'open', 'https://rheacountyheritage.com/', null, 'America/Chicago', now()),
  ('Historic Cherokee Caverns', 'historic-cherokee-caverns', 'roadside-oddities', 35.98002, -84.16514, 'Knoxville', 'TN', 'This privately managed cave opens for selected tours, concerts and seasonal events rather than maintaining ordinary daily cave hours. Its large underground rooms give Knoxville an unusual event venue beneath the surface.', 'limited', 'https://www.historiccherokeecaverns.com/', null, 'America/Chicago', now()),
  ('International Towing & Recovery Museum', 'international-towing-recovery-museum', 'museums', 35.01692, -85.32315, 'Chattanooga', 'TN', 'Antique wreckers, towing equipment and industry artifacts fill a museum devoted to the tow-truck trade, which has deep roots in Chattanooga. The Wall of the Fallen also memorializes operators killed while working roadside recoveries.', 'open', 'https://towingmuseum.com/', null, 'America/Chicago', now()),
  ('MoonPie General Store', 'moonpie-general-store', 'weird-history', 35.0561, -85.31419, 'Chattanooga', 'TN', 'Chattanooga is the birthplace of MoonPie, and this downtown store leans fully into the marshmallow-and-cookie icon with branded merchandise and regional candy history. It is a compact stop tied to one of the South''s strangest enduring snack identities.', 'open', 'https://www.atlasobscura.com/places/moonpie-general-store', null, 'America/Chicago', now()),
  ('Sculpture Fields at Montague Park', 'sculpture-fields-at-montague-park', 'roadside-oddities', 35.0286, -85.29444, 'Chattanooga', 'TN', 'Large-scale contemporary sculptures rise from a broad former industrial landscape, creating a free outdoor art park where monumental forms can be explored on foot. The scale makes the field feel more like a landscape of strange machines than a conventional gallery.', 'open', 'https://www.sculpturefields.org/', null, 'America/Chicago', now()),
  ('Little Debbie Park', 'little-debbie-park', 'roadside-oddities', 35.05692, -85.07107, 'Collegedale', 'TN', 'Giant sculptures of Little Debbie snack cakes turn a public park into a playful monument to the brand headquartered nearby. Oversized oatmeal creme pies and other familiar treats make the park intentionally absurd without requiring a ticket.', 'open', 'https://www.atlasobscura.com/places/little-debbie-park', null, 'America/Chicago', now()),
  ('Cades Cove Primitive Baptist Church', 'cades-cove-primitive-baptist-church', 'weird-history', 35.60203, -83.81351, 'Townsend', 'TN', 'A nineteenth-century church and adjoining cemetery survive in Cades Cove, preserving traces of the community that existed before creation of the national park. The weathered graves and isolated churchyard give travelers a concrete connection to a landscape whose residents were largely displaced.', 'open', 'https://www.nps.gov/grsm/planyourvisit/cadescove.htm', null, 'America/Chicago', now()),
  ('Greeneville Cumberland Presbyterian Church Cannonball', 'greeneville-cumberland-presbyterian-church-cannonball', 'roadside-oddities', 36.16501, -82.83021, 'Greeneville', 'TN', 'A Civil War cannonball remains embedded in the exterior of this Greeneville church, turning battle damage into a permanent architectural artifact. It is a tiny but unusually direct physical remnant of wartime violence in the middle of town.', 'open', 'https://www.atlasobscura.com/places/greeneville-cumberland-presbyterian-church', null, 'America/Chicago', now()),
  ('Tipton-Haynes State Historic Site', 'tipton-haynes-state-historic-site', 'weird-history', 36.29361, -82.335, 'Johnson City', 'TN', 'The Tipton-Haynes property preserves an eighteenth-century house, outbuildings, a spring and layers of Tennessee political and frontier history. Guided access and seasonal hours make it a check-ahead stop rather than an unrestricted historic landscape.', 'limited', 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites/tipton-haynes.html', null, 'America/Chicago', now()),
  ('Chester Inn State Historic Site', 'chester-inn-state-historic-site', 'weird-history', 36.29409, -82.4741, 'Jonesborough', 'TN', 'One of Jonesborough''s oldest commercial buildings survives as a museum interpreting travelers, politics and life in Tennessee''s oldest town. Its long association with stagecoach-era visitors makes it a physical remnant of early road travel.', 'limited', 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites/chester-inn.html', null, 'America/Chicago', now()),
  ('Rocky Mount State Historic Site', 'rocky-mount-state-historic-site', 'weird-history', 36.40555, -82.33657, 'Piney Flats', 'TN', 'This preserved homestead served as the territorial capital of the Southwest Territory in the 1790s. Living-history interpretation and original structures make the site a rare surviving administrative center from before Tennessee became a state.', 'limited', 'https://www.rockymountmuseum.com/', null, 'America/Chicago', now()),
  ('Sam Houston Schoolhouse State Historic Site', 'sam-houston-schoolhouse-state-historic-site', 'weird-history', 35.80194, -83.90444, 'Maryville', 'TN', 'A one-room schoolhouse preserves the place where Sam Houston taught before his later careers as governor of Tennessee and president of the Republic of Texas. The modest building is an unexpectedly small starting point for an outsized political life.', 'limited', 'https://samhoustonschoolhouse.org/', null, 'America/Chicago', now()),
  ('K-25 History Center', 'k-25-history-center', 'weird-history', 35.93141, -84.39285, 'Oak Ridge', 'TN', 'The museum interprets the enormous K-25 uranium-enrichment complex built for the Manhattan Project. Exhibits explain gaseous diffusion, secrecy and the industrial workforce while keeping visitors safely outside restricted federal areas.', 'open', 'https://k25historycenter.com/', null, 'America/Chicago', now()),
  ('American Museum of Science and Energy', 'american-museum-of-science-and-energy', 'weird-history', 36.01274, -84.25276, 'Oak Ridge', 'TN', 'AMSE explores nuclear science, national-security research and the technologies developed around Oak Ridge. Its hands-on exhibits help translate the city''s secret wartime origins into something visitors can understand without entering controlled facilities.', 'open', 'https://amse.org/', null, 'America/Chicago', now()),
  ('B-1 Flat Top House', 'b-1-flat-top-house', 'weird-history', 36.02285, -84.27191, 'Oak Ridge', 'TN', 'One of Oak Ridge''s standardized wartime houses survives as a reminder of the instant city built to support the Manhattan Project. Its utilitarian prefabricated design reflects how quickly thousands of workers had to be housed under secrecy.', 'roadside', 'https://www.atlasobscura.com/places/oak-ridge-b1-flat-top', null, 'America/Chicago', now()),
  ('Oak Ridge History Museum', 'oak-ridge-history-museum', 'weird-history', 36.01274, -84.26533, 'Oak Ridge', 'TN', 'This local museum focuses on everyday life in the secret wartime city, including housing, schools, security and the people who built Oak Ridge. It complements the larger science museums by emphasizing the strange social reality of a city that barely existed on public maps.', 'open', 'https://www.oakridgemuseum.com/', null, 'America/Chicago', now()),
  ('Bell Witch Cave', 'bell-witch-cave', 'folklore', 36.58997, -87.06068, 'Adams', 'TN', 'The Bell Witch legend centers on the Bell family and a mysterious entity reported around their Robertson County farm in the early 1800s. The privately operated cave and property turn one of America''s most famous supernatural legends into an actual ticketed destination.', 'limited', 'https://www.bellwitchcave.com/', null, 'America/Chicago', now()),
  ('The Parthenon', 'the-parthenon', 'roadside-oddities', 36.14975, -86.81316, 'Nashville', 'TN', 'Nashville built a full-scale replica of the ancient Parthenon for the 1897 Tennessee Centennial Exposition and later rebuilt it permanently in concrete. Inside stands a colossal Athena statue, making the structure one of the country''s most improbable pieces of civic architecture.', 'open', 'https://www.nashville.gov/departments/parks/parthenon', null, 'America/Chicago', now()),
  ('Hatch Show Print', 'hatch-show-print', 'weird-history', 36.15804, -86.77596, 'Nashville', 'TN', 'One of America''s oldest working letterpress poster shops preserves carved type, blocks and the bold visual language of country-music advertising. Visitors can see how hand-set print design became inseparable from Nashville''s musical identity.', 'open', 'https://hatchshowprint.com/', null, 'America/Chicago', now()),
  ('George Boedecker''s Sculpture Garden', 'george-boedeckers-sculpture-garden', 'roadside-oddities', 36.05698, -86.95677, 'Nashville', 'TN', 'An eccentric private landscape filled with oversized sculptures, repurposed objects and surreal forms sits along the outskirts of Nashville. Because it is private property, OddWay users should view only from lawful public areas unless explicit access is offered.', 'roadside', 'https://www.atlasobscura.com/places/george-boedeckers-sculpture-garden', null, 'America/Chicago', now()),
  ('Old Tennessee State Prison', 'old-tennessee-state-prison', 'weird-history', 36.17781, -86.86597, 'Nashville', 'TN', 'The castle-like former state prison operated from the nineteenth century into the 1990s and later became a recognizable film location. The complex is restricted and unsafe for casual entry; OddWay should route only to lawful exterior viewpoints and never encourage trespassing.', 'roadside', 'https://www.atlasobscura.com/places/old-tennessee-state-prison', null, 'America/Chicago', now()),
  ('Hermitage Hotel Men''s Bathroom', 'hermitage-hotel-mens-bathroom', 'roadside-oddities', 36.16368, -86.78231, 'Nashville', 'TN', 'The ornate Art Deco men''s room inside the historic Hermitage Hotel became famous for its green-and-black tilework and unusual elegance. It is inside an operating hotel, so visitors should treat the stop as part of a respectful hotel visit rather than wandering private areas.', 'limited', 'https://www.thehermitagehotel.com/', null, 'America/Chicago', now()),
  ('United Record Pressing', 'united-record-pressing', 'roadside-oddities', 36.1431, -86.7699, 'Nashville', 'TN', 'One of the world''s best-known vinyl pressing plants has produced records for generations of major artists. Tours and public access vary, making this a check-ahead stop tied to the physical machinery behind Nashville''s music business.', 'limited', 'https://www.urpressing.com/', null, 'America/Chicago', now()),
  ('Hidden Heart of Music Row', 'hidden-heart-of-music-row', 'roadside-oddities', 36.14862, -86.79312, 'Nashville', 'TN', 'A heart-shaped detail hidden in the Music Row streetscape became a small local scavenger-hunt landmark. It is the kind of easily overlooked urban feature that rewards travelers who look beyond the recording studios and industry offices.', 'open', 'https://www.atlasobscura.com/places/hidden-heart-of-music-row', null, 'America/Chicago', now()),
  ('Timothy Demonbreun''s Cave', 'timothy-demonbreuns-cave', 'weird-history', 36.1608, -86.7089, 'Nashville', 'TN', 'A cave along the Cumberland River is traditionally associated with early settler Timothy Demonbreun, who used the river corridor during Nashville''s frontier period. Access around the bluff and riverbank can be constrained, so visitors should remain in designated public areas.', 'limited', 'https://www.atlasobscura.com/places/timothy-demonbreuns-cave', null, 'America/Chicago', now()),
  ('Dragon Park — Fannie Mae Dees Park', 'dragon-park-fannie-mae-dees-park', 'roadside-oddities', 36.13813, -86.80594, 'Nashville', 'TN', 'A long mosaic dragon coils through this neighborhood park, covered in brightly colored tile and community-made details. The creature is climbable public art and has become one of Nashville''s most distinctive non-music landmarks.', 'open', 'https://www.atlasobscura.com/places/dragon-park', null, 'America/Chicago', now()),
  ('Dutchman''s Curve', 'dutchmans-curve', 'weird-history', 36.1275, -86.8493, 'Nashville', 'TN', 'The 1918 collision at Dutchman''s Curve became one of the deadliest train wrecks in U.S. history. A public greenway and historical interpretation allow visitors to understand the disaster without entering active railroad property; tracks should never be crossed or followed.', 'open', 'https://www.atlasobscura.com/places/dutchmans-curve', null, 'America/Chicago', now()),
  ('President James K. Polk''s Tomb', 'president-james-k-polks-tomb', 'weird-history', 36.1666, -86.784, 'Nashville', 'TN', 'James K. Polk''s remains were moved multiple times before arriving at the Tennessee State Capitol grounds. The ornate tomb''s unusual relocation history makes it more than a standard presidential burial site.', 'open', 'https://www.atlasobscura.com/places/president-james-k-polks-tomb', null, 'America/Chicago', now()),
  ('Ryman Alley', 'ryman-alley', 'weird-history', 36.16106, -86.77839, 'Nashville', 'TN', 'The narrow alley behind the Ryman Auditorium has served for generations as a backstage threshold between performers and downtown Nashville. Its loading doors, brick walls and music lore give travelers a less polished view of the city''s most famous venue.', 'open', 'https://www.ryman.com/', null, 'America/Chicago', now()),
  ('Boy Scout Catfish', 'boy-scout-catfish', 'roadside-oddities', 36.11417, -86.80987, 'Nashville', 'TN', 'An oversized catfish sculpture connected with Nashville''s old civic and fairground culture survives as a deliberately strange public-facing landmark. It is a quick photo stop rather than a staffed attraction.', 'roadside', 'https://www.atlasobscura.com/places/boy-scout-catfish', null, 'America/Chicago', now()),
  ('Downtown Presbyterian Church', 'downtown-presbyterian-church', 'roadside-oddities', 36.16317, -86.77976, 'Nashville', 'TN', 'The church''s Egyptian Revival interior and exterior use columns, lotus-like forms and other motifs rarely seen in American Protestant architecture. Public access depends on worship, tours and events, so check before expecting an interior visit.', 'limited', 'https://www.dpchurch.com/', null, 'America/Chicago', now()),
  ('Lane Motor Museum', 'lane-motor-museum', 'museums', 36.14036, -86.73444, 'Nashville', 'TN', 'This museum specializes in strange, tiny, experimental and unconventional vehicles rather than only famous sports cars. Microcars, amphibious machines, unusual prototypes and European oddities make it one of Tennessee''s strongest mechanical-curiosity museums.', 'open', 'https://www.lanemotormuseum.org/', null, 'America/Chicago', now()),
  ('Saint Mary of the Seven Sorrows Catholic Church', 'saint-mary-of-the-seven-sorrows-catholic-church', 'weird-history', 36.16578, -86.78158, 'Nashville', 'TN', 'One of Nashville''s oldest surviving churches retains nineteenth-century architecture and a long urban history amid modern downtown development. It remains an active sacred space, so visitors should enter only during appropriate public hours.', 'limited', 'https://stmarysdowntown.org/', null, 'America/Chicago', now()),
  ('Edgehill Polar Bears', 'edgehill-polar-bears', 'roadside-oddities', 36.14201, -86.78656, 'Nashville', 'TN', 'Large white polar-bear statues preserve the memory of a long-gone frozen-custard business in the Edgehill neighborhood. The animals survived their original commercial purpose and became neighborhood mascots in their own right.', 'open', 'https://www.atlasobscura.com/places/edgehill-polar-bears', null, 'America/Chicago', now()),
  ('Welcome to 1979', 'welcome-to-1979', 'roadside-oddities', 36.1607, -86.84501, 'Nashville', 'TN', 'This recording and mastering studio deliberately cultivates an analog environment filled with vintage gear and record-making technology. Public visits are not guaranteed, so OddWay should treat it as an appointment, event or check-ahead music-industry stop.', 'limited', 'https://www.welcometo1979.com/', null, 'America/Chicago', now()),
  ('Site of the Z. Alexander Looby House Bombing', 'site-of-the-z-alexander-looby-house-bombing', 'weird-history', 36.16831, -86.80861, 'Nashville', 'TN', 'A bombing destroyed civil-rights attorney Z. Alexander Looby''s home in 1960 and helped trigger a major student march on Nashville City Hall. The residential location should be approached as a history stop from public space, with respect for current neighbors.', 'roadside', 'https://www.atlasobscura.com/places/z-alexander-looby-house-bombing-site', null, 'America/Chicago', now()),
  ('Third Man Records', 'third-man-records', 'roadside-oddities', 36.1522, -86.7782, 'Nashville', 'TN', 'Jack White''s Nashville complex combines a record shop, performance space, studio and novelty-minded vinyl culture under one roof. Its unusual releases, machines and obsession with physical recording formats make it more than a conventional music store.', 'open', 'https://thirdmanrecords.com/pages/nashville-store', null, 'America/Chicago', now()),
  ('Tennessee Pride Sausage Grave', 'tennessee-pride-sausage-grave', 'weird-history', 36.23397, -86.72467, 'Nashville', 'TN', 'The grave associated with the founder of Tennessee Pride became known for imagery tied to the sausage brand and its country-boy mascot. It is a small piece of commercial culture inside a cemetery, so respectful daytime visitation is essential.', 'limited', 'https://www.atlasobscura.com/places/tennessee-pride-sausage-grave', null, 'America/Chicago', now()),
  ('The Nations Silo', 'the-nations-silo', 'roadside-oddities', 36.16462, -86.84974, 'Nashville', 'TN', 'A towering former industrial silo is covered by a monumental mural, turning a remnant of Nashville''s working landscape into a neighborhood landmark. Its scale is difficult to appreciate until standing beneath it.', 'open', 'https://www.atlasobscura.com/places/nations-silo', null, 'America/Chicago', now()),
  ('Butler''s Run', 'butlers-run', 'weird-history', 36.16314, -86.77584, 'Nashville', 'TN', 'This downtown passage preserves the name and history of a narrow historic route once used through the urban block. It is an easy-to-miss fragment of older Nashville embedded within the modern entertainment district.', 'open', 'https://nashvillesites.org/records/butlers-run', null, 'America/Chicago', now()),
  ('Captain William Driver Grave', 'captain-william-driver-grave', 'weird-history', 36.14753, -86.76948, 'Nashville', 'TN', 'Sea captain William Driver, credited with popularizing the nickname ''Old Glory'' for the U.S. flag, is buried in Nashville City Cemetery. The grave provides a physical endpoint to an odd linguistic story that became national symbolism.', 'limited', 'https://www.atlasobscura.com/places/captain-william-driver-grave', null, 'America/Chicago', now()),
  ('Bridgestone Arena Smilodon Bones', 'bridgestone-arena-smilodon-bones', 'museums', 36.1592, -86.7785, 'Nashville', 'TN', 'Fossils from a saber-toothed cat were discovered during construction near the arena, inspiring the Nashville Predators'' saber-toothed identity. Displays or references to the find are tied to the venue, so access may depend on arena hours or events.', 'limited', 'https://www.atlasobscura.com/places/bridgestone-arena-smilodon-bones', null, 'America/Chicago', now()),
  ('8th Avenue Reservoir', '8th-avenue-reservoir', 'roadside-oddities', 36.13943, -86.78075, 'Nashville', 'TN', 'A large historic water reservoir sits unexpectedly close to central Nashville, enclosed by infrastructure and fencing rather than designed as a tourist attraction. View only from lawful public areas and do not cross gates or barriers.', 'roadside', 'https://www.atlasobscura.com/places/nashville-8th-ave-reservoir', null, 'America/Chicago', now()),
  ('Nashville Clayscape', 'nashville-clayscape', 'roadside-oddities', 36.15409, -86.72564, 'Nashville', 'TN', 'A large ceramic public-art installation creates a strange miniature landscape of sculpted forms rather than a conventional statue. Its tactile, earth-toned construction makes it an unusual break from Nashville''s bronze monuments and music murals.', 'open', 'https://www.atlasobscura.com/places/nashville-clayscape', null, 'America/Chicago', now()),
  ('Rock Quarry Cave', 'rock-quarry-cave', 'weird-history', 36.3166, -87.71318, 'Erin', 'TN', 'An old quarry opening has attracted explorers because of its dramatic man-made cavern appearance, but current access is posted and should not be treated as public. OddWay should route only to lawful exterior viewpoints and explicitly discourage entry or trespassing.', 'roadside', 'https://www.atlasobscura.com/places/rock-quarry-cave', null, 'America/Chicago', now()),
  ('Montgomery Bell Tunnel', 'montgomery-bell-tunnel', 'roadside-oddities', 36.14694, -87.12194, 'Kingston Springs', 'TN', 'Industrialist Montgomery Bell had enslaved laborers cut a tunnel through rock in the early nineteenth century to divert water for an ironworks. The short stone passage survives inside Harpeth River State Park as an unusually visible remnant of early industrial engineering and coerced labor.', 'open', 'https://tnstateparks.com/parks/harpeth-river', null, 'America/Chicago', now()),
  ('E.T. Wickham Sculpture Trail', 'et-wickham-sculpture-trail', 'roadside-oddities', 36.4158, -87.4645, 'Palmyra', 'TN', 'Concrete statues and weathered figures created by E.T. Wickham line a rural landscape, forming one of Tennessee''s stranger outsider-art environments. Ownership and access conditions can change; stay on clearly permitted routes and respect posted property boundaries.', 'limited', 'https://www.atlasobscura.com/places/et-wickham-sculpture-trail', null, 'America/Chicago', now()),
  ('Cedars of Lebanon State Park', 'cedars-of-lebanon-state-park', 'roadside-oddities', 36.07369, -86.3115, 'Lebanon', 'TN', 'The park protects rare limestone cedar glades filled with sinkholes, thin soils and plants adapted to extreme conditions. The unusual barrens look deceptively empty but contain one of Middle Tennessee''s most distinctive natural ecosystems.', 'open', 'https://tnstateparks.com/parks/cedars-of-lebanon', null, 'America/Chicago', now()),
  ('Tent Graves of Mt. Gilead Cemetery', 'tent-graves-of-mt-gilead-cemetery', 'weird-history', 35.89534, -85.50331, 'Sparta', 'TN', 'Several graves are covered by pitched stone slabs that resemble tiny tents, a regional burial tradition concentrated in parts of Tennessee and Kentucky. The unusual forms should be viewed respectfully without climbing or disturbing the stones.', 'limited', 'https://www.atlasobscura.com/places/tent-graves', null, 'America/Chicago', now()),
  ('Virgin Falls Pocket Wilderness', 'virgin-falls-pocket-wilderness', 'roadside-oddities', 35.84676, -85.31158, 'Sparta', 'TN', 'A strenuous trail leads through sinkhole and cave-country terrain to a waterfall that emerges from one cave opening and disappears into another. State-owned caves in the area may be closed to protect bats; stay on the designated trail and obey all cave restrictions.', 'limited', 'https://www.atlasobscura.com/places/virgin-falls-pocket-wilderness', null, 'America/Chicago', now()),
  ('Old Stone Fort State Archaeological Park', 'old-stone-fort-state-archaeological-park', 'weird-history', 35.48261, -86.10479, 'Manchester', 'TN', 'An ancient Native American ceremonial enclosure occupies a dramatic plateau above river gorges and waterfalls. As of September 2026, bridge construction affects some vehicle and pedestrian circulation, so check current park alerts before routing.', 'limited', 'https://tnstateparks.com/parks/old-stone-fort', null, 'America/Chicago', now()),
  ('Sewanee Natural Bridge', 'sewanee-natural-bridge', 'roadside-oddities', 35.1541, -85.92316, 'Sewanee', 'TN', 'A naturally eroded sandstone arch spans a wooded ravine on the Cumberland Plateau. The formation resembles deliberately constructed stonework but is entirely geological, making it a compact and easily reached natural oddity.', 'open', 'https://www.tn.gov/environment/natural-areas/what-we-do/sna/cu/natural-bridge.html', null, 'America/Chicago', now()),
  ('The Caverns', 'the-caverns', 'roadside-oddities', 35.33173, -85.82505, 'Pelham', 'TN', 'A large cave has been transformed into a concert venue where audiences watch performers beneath limestone ceilings. Shows, cave tours and access are ticketed, combining geology with one of the country''s most unusual live-music rooms.', 'limited', 'https://www.thecaverns.com/', null, 'America/Chicago', now()),
  ('High Point Restaurant — RyeMabee Mansion', 'high-point-restaurant-ryemabee-mansion', 'roadside-oddities', 35.2393, -85.82872, 'Monteagle', 'TN', 'This stone mansion is wrapped in stories linking it to Al Capone-era travel and Prohibition folklore, although some claims are difficult to verify. Today it operates as a restaurant, allowing visitors to experience the unusual house legally rather than treating it as an abandoned mystery site.', 'open', 'https://www.atlasobscura.com/places/high-point-restaurant', null, 'America/Chicago', now()),
  ('Jack Daniel Distillery', 'jack-daniel-distillery', 'weird-history', 35.2836, -86.37013, 'Lynchburg', 'TN', 'The distillery occupies an enormous complex in tiny Lynchburg and still uses the cave spring that helped determine its location. Ticketed tours explain charcoal mellowing, barrelhouses and the industrial process behind one of Tennessee''s most globally recognized products.', 'limited', 'https://www.jackdaniels.com/en-us/visit-us', null, 'America/Chicago', now()),
  ('Meriwether Lewis Monument', 'meriwether-lewis-monument', 'weird-history', 35.5073, -87.4598, 'Hohenwald', 'TN', 'Explorer Meriwether Lewis died under mysterious circumstances at Grinder''s Stand along the Natchez Trace in 1809. A monument and gravesite mark the place, while debate over whether his death was suicide or murder has persisted for generations.', 'open', 'https://www.nps.gov/natr/learn/historyculture/exploring-the-meriwether-lewis-site.htm', null, 'America/Chicago', now()),
  ('Minnie Pearl Chicken-Wire Statue', 'minnie-pearl-chicken-wire-statue', 'roadside-oddities', 35.77867, -87.46685, 'Centerville', 'TN', 'A folk-art portrait of comedian Minnie Pearl uses chicken wire and other humble materials to honor the Centerville native. The intentionally homespun construction suits the public persona that made her a Grand Ole Opry icon.', 'open', 'https://www.atlasobscura.com/places/minnie-pearl-chicken-wire-statue', null, 'America/Chicago', now()),
  ('Johnny Cash ''One Piece at a Time'' Cadillac', 'johnny-cash-one-piece-at-a-time-cadillac', 'roadside-oddities', 35.95343, -87.32702, 'Bon Aqua', 'TN', 'The Storytellers Museum displays a bizarre Cadillac assembled in the spirit of Johnny Cash''s song ''One Piece at a Time.'' Its mismatched body parts turn a novelty-song premise into a real, drivable-looking object tied to Cash''s former farm area.', 'limited', 'https://www.storytellersmuseum.com/', null, 'America/Chicago', now()),
  ('World''s Largest Cedar Bucket', 'worlds-largest-cedar-bucket', 'roadside-oddities', 35.8438, -86.3962, 'Murfreesboro', 'TN', 'A massive wooden bucket built by a local cooperage became a Murfreesboro landmark and was later rebuilt after a fire. The absurdly oversized container is preserved in Cannonsburgh Village as a piece of old-fashioned promotional craftsmanship.', 'open', 'https://www.murfreesborotn.gov/2476/Worlds-Largest-Cedar-Bucket', null, 'America/Chicago', now()),
  ('Granville Whiskey Decanter Museum', 'granville-whiskey-decanter-museum', 'museums', 36.27175, -85.79708, 'Granville', 'TN', 'Historic Granville displays roughly 5,000 limited-edition whiskey decanters shaped like vehicles, people, animals, landmarks and other objects. The collection is promoted as the world''s largest of its kind and operates on Granville''s limited weekly museum schedule.', 'limited', 'https://www.granvilletn.com/whiskey-decanter-museum', null, 'America/Chicago', now()),
  ('Clement Railroad Hotel Museum', 'clement-railroad-hotel-museum', 'weird-history', 36.07537, -87.38883, 'Dickson', 'TN', 'A former railroad hotel beside the tracks interprets travel, local history and the family of Tennessee governor Frank Clement. Its preserved railroad-era setting makes it a strong reminder of the town''s life around passenger rail.', 'limited', 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites/hotel-halbrook.html', null, 'America/Chicago', now()),
  ('Crystal Shrine Grotto', 'crystal-shrine-grotto', 'roadside-oddities', 35.11044, -89.874, 'Memphis', 'TN', 'Artist Dionicio Rodriguez transformed part of Memorial Park Cemetery into a crystal-studded artificial cave filled with biblical tableaux and faux-natural concrete forms. The grotto feels like a fantasy cavern hidden inside an otherwise conventional cemetery landscape.', 'open', 'https://www.atlasobscura.com/places/the-crystal-shrine-grotto', null, 'America/Chicago', now()),
  ('National Civil Rights Museum', 'national-civil-rights-museum', 'weird-history', 35.13469, -90.0577, 'Memphis', 'TN', 'The museum incorporates the Lorraine Motel, where Martin Luther King Jr. was assassinated in 1968, and traces a broad history of the struggle for civil rights. The preserved motel exterior and room context make this a major dark-history site that should be approached with appropriate seriousness.', 'open', 'https://www.civilrightsmuseum.org/', null, 'America/Chicago', now()),
  ('Peabody Duck March', 'peabody-duck-march', 'folklore', 35.14267, -90.05181, 'Memphis', 'TN', 'Twice daily, a small flock of ducks marches between a rooftop palace and the Peabody Hotel lobby fountain under the direction of a ceremonial Duckmaster. The ritual has become one of America''s strangest long-running hotel traditions.', 'limited', 'https://www.peabodymemphis.com/peabody-ducks', null, 'America/Chicago', now()),
  ('Silky O''Sullivan''s Goats', 'silky-osullivans-goats', 'roadside-oddities', 35.13957, -90.05199, 'Memphis', 'TN', 'This Beale Street bar became famous for keeping goats in an outdoor enclosure and leaning heavily into eccentric Memphis nightlife tradition. Access follows the operating business and age rules rather than functioning as a standalone animal attraction.', 'open', 'https://silkyosullivans.com/', null, 'America/Chicago', now()),
  ('Mud Island River Park', 'mud-island-river-park', 'roadside-oddities', 35.1529, -90.0575, 'Memphis', 'TN', 'The park contains a long-scale model of the lower Mississippi River that visitors can physically walk alongside. The concrete Riverwalk turns hundreds of miles of geography into an oversized outdoor map and is most practical during normal park operating periods.', 'limited', 'https://www.memphisriverparks.org/', null, 'America/Chicago', now()),
  ('Sun Studio', 'sun-studio', 'weird-history', 35.13929, -90.03771, 'Memphis', 'TN', 'The tiny studio where Elvis Presley, Johnny Cash, Jerry Lee Lewis and others recorded is preserved as a guided-tour destination. Its modest size contrasts sharply with its enormous influence on rock and roll history.', 'limited', 'https://www.sunstudio.com/', null, 'America/Chicago', now()),
  ('Jungle Room at Graceland', 'jungle-room-at-graceland', 'roadside-oddities', 35.04611, -90.02583, 'Memphis', 'TN', 'Elvis Presley''s Jungle Room is an aggressively themed interior of green carpet, carved furniture, faux-waterfall décor and 1970s excess. It is accessible only as part of authorized Graceland admission rather than as a separate room visitors can enter freely.', 'limited', 'https://www.graceland.com/', null, 'America/Chicago', now()),
  ('Woodruff-Fontaine House Museum', 'woodruff-fontaine-house-museum', 'haunted', 35.14498, -90.03767, 'Memphis', 'TN', 'This ornate Victorian mansion preserves period interiors and has accumulated long-running stories of apparitions and unexplained activity. The house operates as a legitimate museum, giving visitors a structured way to experience the building without relying on trespass-based ghost hunting.', 'limited', 'https://woodruff-fontaine.org/', null, 'America/Chicago', now()),
  ('Earnestine & Hazel''s', 'earnestine-hazels', 'haunted', 35.13296, -90.05927, 'Memphis', 'TN', 'A former pharmacy and later nightclub became a beloved dive bar with layers of Memphis music, vice and ghost lore. Stories of unexplained jukebox behavior and apparitions are part of its reputation, but the building is best experienced as an operating business with documented history.', 'open', 'https://earnestineandhazels.com/', null, 'America/Chicago', now()),
  ('House of Mews', 'house-of-mews', 'roadside-oddities', 35.12017, -89.99123, 'Memphis', 'TN', 'This cat-focused nonprofit adoption space and shop has placed rescued cats at the center of a retail storefront for decades. For travelers, it functions as an unexpectedly feline destination in the middle of Cooper-Young.', 'open', 'https://houseofmews.com/', null, 'America/Chicago', now()),
  ('Memphis Gong Chamber', 'memphis-gong-chamber', 'roadside-oddities', 35.12176, -89.99064, 'Memphis', 'TN', 'A private sound space built around large gongs offers immersive vibration and resonance sessions unlike a conventional concert. Visits are appointment-based, so travelers should never expect walk-in access.', 'limited', 'https://www.atlasobscura.com/places/memphis-gong-chamber', null, 'America/Chicago', now()),
  ('Elmwood Cemetery', 'elmwood-cemetery', 'weird-history', 35.12183, -90.02901, 'Memphis', 'TN', 'Memphis''s historic garden cemetery contains elaborate monuments, mass-grave history, yellow-fever burials and generations of the city''s political and cultural figures. Its funerary art and difficult history make it an outdoor archive rather than simply a famous-person graveyard.', 'limited', 'https://www.elmwoodcemetery.org/', null, 'America/Chicago', now()),
  ('Belz Museum of Asian and Judaic Art', 'belz-museum-of-asian-and-judaic-art', 'museums', 35.1419, -90.05436, 'Memphis', 'TN', 'Large carved jade pieces, monumental Asian works and Judaic art fill this downtown museum. The scale and density of the collection make it a surprising hidden museum only steps from Memphis''s better-known music attractions.', 'open', 'https://www.belzmuseum.org/', null, 'America/Chicago', now()),
  ('Blues Hall of Fame Museum', 'blues-hall-of-fame-museum', 'weird-history', 35.13478, -90.05725, 'Memphis', 'TN', 'The Blues Foundation''s museum honors musicians, recordings and artifacts connected to the blues tradition. Its location near the Mississippi River and civil-rights landmarks makes it a concentrated stop for the music that shaped much of American popular culture.', 'open', 'https://blues.org/hall-of-fame-museum/', null, 'America/Chicago', now()),
  ('Al Green''s Full Gospel Tabernacle Church', 'al-greens-full-gospel-tabernacle-church', 'weird-history', 35.02623, -90.03782, 'Memphis', 'TN', 'Soul singer Al Green became a minister and has long preached at this active Memphis church. It is a functioning house of worship, not a performance attraction; visitors should attend only public services, dress appropriately and respect the congregation.', 'limited', 'https://www.atlasobscura.com/places/al-greens-full-gospel-tabernacle-church', null, 'America/Chicago', now()),
  ('Beale Street Hoodoo History & Folklife Museum', 'beale-street-hoodoo-history-folklife-museum', 'folklore', 35.13955, -90.05276, 'Memphis', 'TN', 'Located above A. Schwab on Beale Street, this museum explores hoodoo, folk belief, spiritual practices and the cultural history surrounding the district. It gives physical context to traditions often sensationalized elsewhere and should be visited during posted museum access.', 'limited', 'https://hoodoomuseum.org/', null, 'America/Chicago', now()),
  ('Memphis Listening Lab', 'memphis-listening-lab', 'roadside-oddities', 35.15214, -90.01559, 'Memphis', 'TN', 'Thousands of records, CDs, books and music-related materials form a public listening library where visitors can actually hear much of the collection. The emphasis on deep listening rather than retail makes it an unusually hands-on archive of recorded sound.', 'open', 'https://memphislisteninglab.org/', null, 'America/Chicago', now()),
  ('Overton Park Shell', 'overton-park-shell', 'weird-history', 35.14547, -89.99455, 'Memphis', 'TN', 'This open-air bandshell hosted an early Elvis Presley performance and survived repeated threats of demolition. Free concerts and events continue the venue''s history, but access to programmed areas depends on the park and event schedule.', 'limited', 'https://overtonparkshell.org/', null, 'America/Chicago', now()),
  ('Metal Museum at Overton Park', 'metal-museum-at-overton-park', 'museums', 35.1448, -89.9932, 'Memphis', 'TN', 'The Metal Museum moved to 1930 Poplar Avenue in Overton Park, expanding its focus on metalworking, sculpture and live craft demonstrations. As of September 9, 2026, the official site says the museum is temporarily closed and will reopen Friday, September 11, 2026; re-check before routing.', 'limited', 'https://www.metalmuseum.org/directions', null, 'America/Chicago', now()),
  ('Big Kids Sculptures', 'big-kids-sculptures', 'roadside-oddities', 35.15343, -90.01102, 'Memphis', 'TN', 'Large childlike figures in public space exaggerate ordinary play into oversized sculpture. Their scale and cartoonish presence make the installation an easy OddWay-style visual stop rather than a traditional monument.', 'open', 'https://www.atlasobscura.com/places/big-kids-sculptures', null, 'America/Chicago', now()),
  ('Shelby Farms Park Buffalo Herd', 'shelby-farms-park-buffalo-herd', 'roadside-oddities', 35.13881, -89.8325, 'Memphis', 'TN', 'A resident herd of American bison lives inside one of the country''s largest urban parks. Seeing massive prairie animals within metropolitan Memphis creates a surreal contrast with the surrounding city and greenway network.', 'open', 'https://www.shelbyfarmspark.org/', null, 'America/Chicago', now()),
  ('Memphis Chess Club', 'memphis-chess-club', 'roadside-oddities', 35.14397, -90.05008, 'Memphis', 'TN', 'One of the country''s historic chess organizations operates a downtown clubhouse centered on casual play, tournaments and chess culture. It gives travelers a niche social-history stop in a city better known for music and food.', 'open', 'https://www.memphischessclub.com/', null, 'America/Chicago', now()),
  ('The Four Way', 'the-four-way', 'weird-history', 35.11976, -90.04127, 'Memphis', 'TN', 'This historic soul-food restaurant served major civil-rights figures, musicians and neighborhood residents through decades of Memphis history. Its significance lies as much in the conversations and community it hosted as in the food itself.', 'open', 'https://www.atlasobscura.com/places/the-four-way', null, 'America/Chicago', now()),
  ('Bass Pro Shops at the Pyramid', 'bass-pro-shops-at-the-pyramid', 'roadside-oddities', 35.15545, -90.05199, 'Memphis', 'TN', 'A gigantic stainless-steel pyramid originally built as an arena now contains a vast outdoor-retail complex, hotel, swamp-like interior and elevated observation deck. The sheer mismatch between ancient-Egypt-inspired architecture and its current use makes it peak OddWay.', 'open', 'https://stores.basspro.com/us/tn/memphis/1-bass-pro-dr.html', null, 'America/Chicago', now()),
  ('Stax Museum of American Soul Music', 'stax-museum-of-american-soul-music', 'weird-history', 35.11578, -90.0312, 'Memphis', 'TN', 'Built on the site of Stax Records, the museum preserves the story of the integrated label that produced Otis Redding, Isaac Hayes and many other soul artists. Exhibits include stage clothing, recording history and famously extravagant vehicles.', 'open', 'https://staxmuseum.com/', null, 'America/Chicago', now()),
  ('Slave Haven Underground Railroad Museum — Burkle Estate', 'slave-haven-underground-railroad-museum-burkle-estate', 'weird-history', 35.16464, -90.04326, 'Memphis', 'TN', 'The Burkle Estate interprets local slavery, escape networks and Underground Railroad history through guided museum visits. Claims about specific secret passages should be understood through the museum''s interpretation, but the broader history of slavery and resistance is central to the stop.', 'limited', 'https://slavehavenmemphis.com/', null, 'America/Chicago', now()),
  ('C.H. Nash Museum at Chucalissa', 'ch-nash-museum-at-chucalissa', 'weird-history', 35.06231, -90.13009, 'Memphis', 'TN', 'Built beside a Mississippian mound complex, Chucalissa interprets Indigenous archaeology and the long history of Native communities in the Mississippi Valley. The preserved earthworks make the site a substantial archaeological landscape inside modern Memphis.', 'open', 'https://www.memphis.edu/chucalissa/', null, 'America/Chicago', now()),
  ('Cotton Museum at the Memphis Cotton Exchange', 'cotton-museum-at-the-memphis-cotton-exchange', 'weird-history', 35.14332, -90.0547, 'Memphis', 'TN', 'The former Cotton Exchange trading floor explains how cotton shaped Memphis commerce while confronting the crop''s connections to enslaved labor and the postwar agricultural economy. Original market infrastructure gives the museum an unusually direct setting.', 'open', 'https://www.memphiscottonmuseum.org/', null, 'America/Chicago', now()),
  ('Memphis Railroad & Trolley Museum', 'memphis-railroad-trolley-museum', 'museums', 35.13207, -90.05916, 'Memphis', 'TN', 'Located at Central Station, this volunteer-run museum preserves Memphis railroad and streetcar history through models, artifacts and transportation exhibits. Limited operating schedules make it a check-ahead destination rather than a guaranteed daily stop.', 'limited', 'https://mrtm.org/', null, 'America/Chicago', now()),
  ('W.C. Handy Home and Museum', 'wc-handy-home-and-museum', 'weird-history', 35.13972, -90.04956, 'Memphis', 'TN', 'The modest house associated with composer W.C. Handy, often called the Father of the Blues, was moved to Beale Street and preserved as a small museum. Its scale provides a sharp contrast with the enormous cultural influence of the music created around it.', 'limited', 'https://www.memphistravel.com/arts-culture/wc-handy-home-museum', null, 'America/Chicago', now()),
  ('Museum of Science & History — Pink Palace Mansion', 'museum-of-science-history-pink-palace-mansion', 'roadside-oddities', 35.12488, -89.95953, 'Memphis', 'TN', 'A massive pink-marble mansion built for Piggly Wiggly founder Clarence Saunders became the centerpiece of Memphis''s science and history museum. The unfinished personal palace turned public museum mixes eccentric architecture with natural-history and regional exhibits.', 'open', 'https://moshmemphis.com/', null, 'America/Chicago', now()),
  ('Withers Collection Museum & Gallery', 'withers-collection-museum-gallery', 'weird-history', 35.13938, -90.05035, 'Memphis', 'TN', 'Photographer Ernest Withers documented the civil-rights movement, Memphis music and Black life across the twentieth-century South. The Beale Street gallery presents that immense visual record while also confronting the complicated later revelations about Withers''s FBI relationship.', 'open', 'https://thewitherscollection.com/', null, 'America/Chicago', now()),
  ('Tina Turner Museum at Flagg Grove School', 'tina-turner-museum-at-flagg-grove-school', 'weird-history', 35.54108, -89.24605, 'Brownsville', 'TN', 'The one-room schoolhouse Tina Turner attended was moved and restored as a museum devoted to her life and career. Costumes, memorabilia and the tiny rural classroom connect an international superstar to her West Tennessee beginnings.', 'open', 'https://westtnheritage.com/tina-turner-museum/', null, 'America/Chicago', now()),
  ('Billy Tripp''s Mindfield', 'billy-tripps-mindfield', 'roadside-oddities', 35.59283, -89.2669, 'Brownsville', 'TN', 'Billy Tripp has spent decades assembling towering steel beams, signs, found objects and personal symbols into an ever-growing outdoor sculpture. The work resembles a private industrial monument gradually consuming its lot and is one of Tennessee''s premier outsider-art landmarks.', 'open', 'https://www.atlasobscura.com/places/billy-tripps-mindfield', null, 'America/Chicago', now()),
  ('Alex Haley Museum & Interpretive Center', 'alex-haley-museum-interpretive-center', 'weird-history', 35.67337, -89.57646, 'Henning', 'TN', 'The childhood home of Roots author Alex Haley is preserved as a museum interpreting his family history, writing and the enormous cultural impact of Roots. The site connects national conversations about ancestry and slavery to a specific West Tennessee community.', 'limited', 'https://www.tn.gov/historicalcommission/state-programs/state-historic-sites.html', null, 'America/Chicago', now()),
  ('National Bird Dog Museum', 'national-bird-dog-museum', 'museums', 35.04982, -89.1933, 'Grand Junction', 'TN', 'A museum devoted to pointing dogs, field trials and sporting-dog history contains trophies, art and breed-specific displays. Its singular subject matter makes it one of the state''s strongest niche museums.', 'open', 'https://www.birddogfoundation.com/', null, 'America/Chicago', now()),
  ('Trenton Teapot Museum', 'trenton-teapot-museum', 'museums', 35.97825, -88.94135, 'Trenton', 'TN', 'An unusual municipal collection displays hundreds of ornate teapots, including elaborate porcelain and novelty forms gathered over generations. The obsessive single-object theme fits OddWay better than a conventional local-history museum.', 'limited', 'https://www.atlasobscura.com/places/trenton-teapot-museum', null, 'America/Chicago', now()),
  ('Tennessee Safari Park', 'tennessee-safari-park', 'roadside-oddities', 35.7677, -89.12577, 'Alamo', 'TN', 'A drive-through route brings visitors past camels, zebras, antelope and other animals in rural West Tennessee. The surreal roadside contrast of exotic species against farmland makes the park a memorable route stop; follow all posted feeding and vehicle rules.', 'limited', 'https://tennesseesafaripark.com/', null, 'America/Chicago', now()),
  ('Casey Jones Home & Railroad Museum', 'casey-jones-home-railroad-museum', 'folklore', 35.66054, -88.85496, 'Jackson', 'TN', 'Engineer Casey Jones died in a 1900 train collision and was transformed into an American folk hero through song and storytelling. His preserved home and railroad museum turn the legend back into a specific person, place and fatal event.', 'open', 'https://caseyjones.com/', null, 'America/Chicago', now()),
  ('Pinson Mounds State Archaeological Park', 'pinson-mounds-state-archaeological-park', 'weird-history', 35.4975, -88.68674, 'Pinson', 'TN', 'This complex preserves some of the largest Middle Woodland ceremonial earthworks in the United States, including towering mounds built nearly two thousand years ago. Trails and a museum allow legal exploration without treating Indigenous sacred landscapes as mysterious ruins.', 'open', 'https://tnstateparks.com/parks/pinson-mounds', null, 'America/Chicago', now()),
  ('Patsy Cline Crash Site Memorial', 'patsy-cline-crash-site-memorial', 'weird-history', 36.06007, -88.15898, 'Camden', 'TN', 'A memorial in the woods marks the area where a 1963 plane crash killed Patsy Cline, Cowboy Copas, Hawkshaw Hawkins and Randy Hughes. The route can be muddy or rough, and the site should be treated as a memorial rather than a disaster-photo attraction.', 'limited', 'https://www.atlasobscura.com/places/patsy-cline-crash-site-memorial', null, 'America/Chicago', now()),
  ('Eiffel Tower Park', 'eiffel-tower-park', 'roadside-oddities', 36.28678, -88.30011, 'Paris', 'TN', 'Paris, Tennessee answers its French namesake with a large Eiffel Tower replica rising over a city park. The intentionally literal landmark is classic small-city roadside branding and an easy photo stop.', 'open', 'https://www.paristn.gov/', null, 'America/Chicago', now()),
  ('Tennessee River Freshwater Pearl Museum', 'tennessee-river-freshwater-pearl-museum', 'museums', 35.96867, -88.04889, 'Camden', 'TN', 'Birdsong Resort''s pearl operation interprets Tennessee River freshwater pearls, mussels and the unusual industry built around them. Museum access and pearl-farm activities can be seasonal or scheduled, so check before making a dedicated trip.', 'limited', 'https://www.birdsongresort.com/', null, 'America/Chicago', now()),
  ('Buford Pusser Home & Museum', 'buford-pusser-home-museum', 'weird-history', 35.23175, -88.3836, 'Adamsville', 'TN', 'The former home of sheriff Buford Pusser preserves artifacts connected to the violent law-enforcement career that inspired Walking Tall. The museum separates the real West Tennessee figure from the larger-than-life movie mythology built around him.', 'open', 'https://www.bufordpussermuseum.com/', null, 'America/Chicago', now()),
  ('Fort Pillow State Historic Park', 'fort-pillow-state-historic-park', 'weird-history', 35.6403, -89.8365, 'Henning', 'TN', 'Fort Pillow preserves earthworks from the Civil War site where Confederate forces under Nathan Bedford Forrest captured the fort in 1864 and killed large numbers of Black Union troops after overrunning the position. The park interprets the battlefield and massacre through trails, exhibits and preserved terrain.', 'open', 'https://www.tnstateparks.com/parks/fort-pillow', null, 'America/Chicago', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as tennessee from public.stops where state = 'TN';
